# The application's identity is defined ONCE, here. Do not change it anywhere else:
#   - the copyright year updates automatically (current year);
#   - the version is injected at build time from the GitHub Release
#     (cardvault/_version.py, generated by the workflow / tools/set_version.py).

from datetime import date as _date

APP_NAME = "CardVault"
AUTHOR = "Gabriel Dobre"
COPYRIGHT_HOLDER = AUTHOR

# First year of copyright. The displayed range extends automatically
# (e.g. "2026–2027") as time passes, with no manual changes.
COPYRIGHT_START_YEAR = 2026


def _copyright_year() -> str:
    y = _date.today().year
    if y <= COPYRIGHT_START_YEAR:
        return str(COPYRIGHT_START_YEAR)
    return f"{COPYRIGHT_START_YEAR}–{y}"


def copyright_line() -> str:
    """Full copyright notice, computed at run time."""
    return f"© {_copyright_year()} {COPYRIGHT_HOLDER}. All rights reserved."


def copyright_short() -> str:
    return f"© {_copyright_year()} {COPYRIGHT_HOLDER}"


# Version: injected at build time. Defaults to "dev" when running from source.
try:
    from ._version import __version__ as APP_VERSION
except Exception:
    APP_VERSION = "0.0.0-dev"

# Dynamic values kept for compatibility with existing code.
COPYRIGHT_YEAR = _copyright_year()
COPYRIGHT = copyright_short()
